  var BJ_V = {'অ':'A','আ':'Av','ই':'B','ঈ':'C','উ':'D','ঊ':'E','ঋ':'F','এ':'G','ঐ':'H','ও':'I','ঔ':'J'};
  var BJ_M = {'ং':'s','ঃ':'t','ঁ':'u'};
  var BJ_D = {'০':'0','১':'1','২':'2','৩':'3','৪':'4','৫':'5','৬':'6','৭':'7','৮':'8','৯':'9','।':'|'};
  var BJ_PRE = {'ি':'w','ে':'‡','ৈ':'‰'}, BJ_POST = {'া':'v','ী':'x','ু':'y','ূ':'z','ৃ':'„'};
